    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long x;
    cin >> n >> x;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    printList(partition(buildList(a), x));

    return 0;
